fn toggle_case(s: Vec<char>) -> Vec<char> {
    s.into_iter()
     .map(|c| {
         if c.is_ascii_lowercase() {
             // 'a'..='z' → 'A'..='Z'
             c.to_ascii_uppercase()
         } else if c.is_ascii_uppercase() {
             // 'A'..='Z' → 'a'..='z'
             c.to_ascii_lowercase()
         } else {
             // Non-alphabetic characters remain unchanged
             c
         }
     })
     .collect()
}

